(()=>{
let client,user=null,initPromise,syncing=false,ready=false,timer,retry=1000,conflicted=false,authBusy=false;
const msg=s=>$('#authMessage').textContent=s,status=s=>$('#syncStatus').textContent=s,baselineKey=id=>'ritim-sync-'+id,cacheKey=id=>'ritim-user-'+id;
function read(k,f){try{return JSON.parse(localStorage.getItem(k))||f}catch{return f}}
function store(k,v){localStorage.setItem(k,JSON.stringify(v))}
function rowsOf(s){return {settings:s.categories,...Object.fromEntries(Object.entries(s.days).map(([d,v])=>[d,v.entries]))}}
function gate(){document.documentElement.dataset.auth=user?'signed-in':'signed-out';$('#signedIn').hidden=!user;$('#signedOut').hidden=!!user;$('#accountEmail').textContent=user?.email||'';$('#accountButton').textContent=user?'Hesabım':'Giriş yap';document.querySelectorAll('[data-close="#accountDialog"]').forEach(b=>b.hidden=!user);if(!user&&!$('#accountDialog').open)$('#accountDialog').showModal();document.querySelector('main').inert=!!user&&!ready}
function switchUser(next){if(user?.id===next?.id){gate();return}clearTimeout(timer);ready=false;conflicted=false;user=next;activeStorageKey=user?cacheKey(user.id):KEY;const cached=read(activeStorageKey,null);state=cached||freshState();save();render();if(user&&!cached){store(baselineKey(user.id),Object.fromEntries(Object.entries(rowsOf(state)).map(([k,v])=>[k,{text:JSON.stringify(v),stamp:null}])))}gate();if(user){$('#accountDialog').close();startSync(true)}else msg('Planına erişmek için GitHub ile giriş yap.')}
function init(){return initPromise??=initialize().catch(e=>{initPromise=null;throw e})}
async function initialize(){const {createClient}=await import('https://cdn.jsdelivr.net/npm/@supabase/supabase-js@2.105.0/+esm');client=createClient(window.RITIM_SUPABASE.url,window.RITIM_SUPABASE.key,{auth:{flowType:'pkce'}});const {data,error}=await client.auth.getSession();if(error)throw error;switchUser(data.session?.user||null);client.auth.onAuthStateChange((_event,session)=>setTimeout(()=>switchUser(session?.user||null),0));gate()}
function conflict(message){const e=Error(message);e.conflict=true;return e}
async function sync(full=true){if(!user)throw Error('Önce giriş yap.');const id=user.id,baseline=read(baselineKey(id),{}),local=structuredClone(state),localRows=rowsOf(local),remoteRows={};const sameUser=()=>{if(user?.id!==id)throw Error('Oturum değişti; eşitleme durduruldu.')};
const dirty=Object.keys(localRows).filter(k=>JSON.stringify(localRows[k])!==baseline[k]?.text||baseline[k]?.stamp===null);const keysToRead=full?null:dirty;
if(full||dirty.includes('settings')){const r=await client.from('planner_settings').select('categories,updated_at').eq('user_id',id).maybeSingle();if(r.error)throw r.error;if(r.data)remoteRows.settings={value:r.data.categories,stamp:r.data.updated_at}}
if(full){for(let from=0;;from+=500){const r=await client.from('planner_days').select('day,entries,updated_at').eq('user_id',id).order('day').range(from,from+499);if(r.error)throw r.error;for(const d of r.data)remoteRows[d.day]={value:d.entries,stamp:d.updated_at};if(r.data.length<500)break}}else{for(const d of keysToRead.filter(k=>k!=='settings')){const r=await client.from('planner_days').select('entries,updated_at').eq('user_id',id).eq('day',d).maybeSingle();if(r.error)throw r.error;if(r.data)remoteRows[d]={value:r.data.entries,stamp:r.data.updated_at}}}
sameUser();const keys=full?new Set([...Object.keys(remoteRows),...Object.keys(localRows)]):new Set(dirty),plan=[];
for(const key of keys){const remote=remoteRows[key],value=localRows[key],b=baseline[key],text=JSON.stringify(value),rt=JSON.stringify(remote?.value),changed=(!remote&&value!==undefined)||(b?text!==b.text:value!==undefined&&key!=='settings');if(remote&&changed&&(!b||remote.stamp!==b.stamp)&&text!==rt)throw conflict(`${key==='settings'?'Kategoriler':key} başka cihazda da değişmiş. Yerel yedeğini al; çakışma nedeniyle otomatik eşitleme durduruldu.`);plan.push({key,remote,value,write:changed&&text!==rt})}
for(const {key,remote,value,write} of plan){sameUser();let result=remote;if(write){const table=key==='settings'?'planner_settings':'planner_days',column=key==='settings'?'categories':'entries',payload={user_id:id,[column]:value,...(key==='settings'?{}:{day:key})};let q=remote?client.from(table).update({[column]:value}).eq('user_id',id).eq('updated_at',remote.stamp):client.from(table).insert(payload);if(remote&&key!=='settings')q=q.eq('day',key);const r=await q.select(column+',updated_at');if(r.error){if(r.error.code==='23505')throw conflict('Aynı kayıt başka cihazda oluşturuldu. Eşitleme çakışması.');throw r.error}if(r.data.length!==1)throw conflict('Kayıt başka cihazda değişti. Eşitleme çakışması.');result={value:r.data[0][column],stamp:r.data[0].updated_at}}
sameUser();if(result){const current=key==='settings'?state.categories:state.days[key]?.entries;if(JSON.stringify(current)===JSON.stringify(localRows[key])){if(key==='settings')state.categories=result.value;else state.days[key]={entries:result.value}}baseline[key]={text:JSON.stringify(result.value),stamp:result.stamp};store(baselineKey(id),baseline);save()}}
render();status('Otomatik eşitleme açık · Kaydedildi');msg('Tüm değişiklikler otomatik kaydediliyor.');}
function pending(){if(!user)return false;const b=read(baselineKey(user.id),{});return Object.entries(rowsOf(state)).some(([k,v])=>JSON.stringify(v)!==b[k]?.text||b[k]?.stamp===null)}
function schedule(delay=600){if(!user||!ready||conflicted)return;clearTimeout(timer);status('Değişiklikler kaydediliyor…');timer=setTimeout(()=>startSync(false),delay)}
async function startSync(full=false){if(syncing||!user)return;syncing=true;const id=user.id;status('Veritabanıyla eşitleniyor…');try{await sync(full);retry=1000;ready=true;conflicted=false}catch(e){if(user?.id===id){conflicted=!!e.conflict;ready=true;msg(e.message);status(e.conflict?'Eşitleme çakışması · Hesap ekranını aç.':'Bağlantı sorunu · Değişiklikler bu cihazda, yeniden denenecek.');if(!conflicted){clearTimeout(timer);timer=setTimeout(()=>startSync(full),retry);retry=Math.min(retry*2,60000)}}}finally{syncing=false;gate();if(user?.id!==id&&user){startSync(true)}else if(user&&ready&&!conflicted&&pending())schedule(retry===1000?600:retry)}}
globalThis.ritimSaved=()=>{if(!syncing&&user&&ready)schedule()};
$('#accountDialog').addEventListener('cancel',e=>{if(!user)e.preventDefault()});
$('#accountButton').onclick=()=>{$('#accountDialog').showModal();msg(conflicted?'Çakışma var. Önce yerel JSON yedeğini al.':'Değişikliklerin otomatik eşitlenir.')};
$('#githubLogin').onclick=async()=>{if(authBusy)return;authBusy=true;$('#githubLogin').disabled=true;try{await init();const {error}=await client.auth.signInWithOAuth({provider:'github',options:{redirectTo:window.RITIM_SITE_URL}});if(error)throw error}catch(e){msg(e.message||'Giriş bağlantısı kurulamadı. Tekrar dene.')}finally{authBusy=false;$('#githubLogin').disabled=false}};
$('#syncNow').onclick=()=>{conflicted=false;startSync(true)};
$('#signOut').onclick=async()=>{if(syncing||pending()){msg('Kaydedilmemiş değişiklikler var. Önce eşitlemenin tamamlanmasını bekle.');return}const {error}=await client.auth.signOut({scope:'local'});if(error){msg(error.message);return}switchUser(null)};
window.addEventListener('online',()=>{if(user&&!conflicted)startSync(true)});window.addEventListener('focus',()=>{if(user&&ready&&!conflicted)startSync(true)});window.addEventListener('beforeunload',e=>{if(user&&pending()){e.preventDefault();e.returnValue=''}});
gate();init().catch(()=>{gate();msg('Giriş servisine bağlanılamadı. Bağlantını kontrol edip tekrar dene.')});
})();
